//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//삭제사유
scwin.vScrenID = "ULDINS91500.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_register
 * 설명       : 삭제사유 등록
 ***********************************************/
scwin.ins_register = async function() {
    $c.frame.path("../").ins_popupRtn_cdnm(txb_DEL_RSN.getValue(), "");
    $c.frame.path("../").ins_remove();
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_confirm_onclick = function() {
    if (txb_DEL_RSN.getValue() == "" || txb_DEL_RSN.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "사유"));
        txb_DEL_RSN.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_DEL_RSN, 40, "사유")) {
        //txb_DEL_RSN.value = "";
        txb_DEL_RSN.focus();
        return false;
    }

    //var rtn = confirm('삭제 하시겠습니까?')
    //if (rtn == 1) // [삭제] 버튼이 눌려졌을 경우
    //{
    scwin.ins_register();
    //}

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_2);
    var sd = $c.frame.path("../").scwin.vScrenID;
    if (sd == "ULDINS15000.gfm") {
        txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_KOR_NM));
    } else if (sd == "ULDINS15100.gfm" || sd == "ULDINS15200.gfm" || sd == "ULDINS16200.gfm" || sd == "ULDINS16100.gfm") {
        txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_NM) + " " + $c.stf.getObjectValue($c.frame.path("../").txb_UNQ_ISU_NM));
    } else if (sd == "ULDINS15300.gfm" || sd == "ULDINS15500.gfm" || sd == "ULDINS15600.gfm" || sd == "ULDINS15700.gfm") {
        txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_NM));
    } else if (sd == "ULDINS16400.gfm") {
        txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_NM));
    } else if (sd == "ULDINS16600.gfm") {
        txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_KOR_NM));
    }
    txb_KEYVALUE.setValue($c.stf.getObjectValue($c.frame.path("../").txb_STD_CD));
    txb_DEL_RSN.focus();
};
scwin.txb_DEL_RSN_onkeyup = function() {
    //fn_DelChar(this);		

};
